<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';

use TripleR\Config;
use TripleR\Database;

if(!function_exists('curl_init')){fwrite(STDERR,"PHP curl extension is required for M8 HTTP acceptance.\n");exit(2);}
$base=rtrim(Config::require('M4_HTTP_BASE_URL'),'/');$password=Config::require('M4_HTTP_TEST_PASSWORD');$db=Database::connection();$tag=bin2hex(random_bytes(5));$failures=0;
function m8httpcheck(bool $ok,string $name,string $detail=''):void{global $failures;if($ok){echo "PASS: $name\n";return;}$failures++;echo "FAIL: $name".($detail===''?'':" ($detail)")."\n";}
function m8request($client,string $method,string $path,?array $form=null):array{$headers=[];curl_setopt_array($client,[CURLOPT_URL=>$GLOBALS['base'].$path,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>false,CURLOPT_HEADERFUNCTION=>static function($ch,string $line)use(&$headers):int{$n=strlen($line);if(str_contains($line,':')){[$key,$value]=explode(':',$line,2);$headers[strtolower(trim($key))]=trim($value);}return $n;},CURLOPT_FOLLOWLOCATION=>false]);if($method==='POST')curl_setopt_array($client,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($form??[])]);else curl_setopt($client,CURLOPT_HTTPGET,true);$body=curl_exec($client);if(!is_string($body))throw new RuntimeException('M8 HTTP request failed: '.curl_error($client));return ['status'=>(int)curl_getinfo($client,CURLINFO_RESPONSE_CODE),'body'=>$body,'headers'=>$headers];}
function m8login(string $email):array{$client=curl_init();curl_setopt_array($client,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>10]);$page=m8request($client,'GET','/staff/login');if(!preg_match('/name="_csrf"\s+value="([^"]+)"/',$page['body'],$match))throw new RuntimeException('M8 login CSRF token missing.');$login=m8request($client,'POST','/staff/login',['_csrf'=>html_entity_decode($match[1],ENT_QUOTES|ENT_HTML5,'UTF-8'),'email'=>$email,'password'=>$GLOBALS['password']]);if(!in_array($login['status'],[200,303],true))throw new RuntimeException('M8 test login failed for '.$email);$home=m8request($client,'GET','/staff');if(!preg_match('/name="_csrf"\s+value="([^"]+)"/',$home['body'],$match))throw new RuntimeException('M8 staff CSRF token missing.');return [$client,html_entity_decode($match[1],ENT_QUOTES|ENT_HTML5,'UTF-8')];}
function m8multipart($client,string $path,array $form,string $file):array{$form['photo']=new CURLFile($file,'image/png','maintenance.png');$headers=[];curl_setopt_array($client,[CURLOPT_URL=>$GLOBALS['base'].$path,CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>$form,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADERFUNCTION=>static function($ch,string $line)use(&$headers):int{$n=strlen($line);if(str_contains($line,':')){[$key,$value]=explode(':',$line,2);$headers[strtolower(trim($key))]=trim($value);}return $n;},CURLOPT_FOLLOWLOCATION=>false]);$body=curl_exec($client);if(!is_string($body))throw new RuntimeException('M8 multipart request failed: '.curl_error($client));return ['status'=>(int)curl_getinfo($client,CURLINFO_RESPONSE_CODE),'body'=>$body,'headers'=>$headers];}

$accounts=[];foreach(['mechanic','fleet_manager','auditor','front_desk'] as $role){$email="m8-$role-$tag@example.test";$q=$db->prepare('INSERT INTO users(email,password_hash,role,is_active,must_change_password) VALUES(:email,:hash,:role,1,0)');$q->execute(['email'=>$email,'hash'=>password_hash($password,PASSWORD_DEFAULT),'role'=>$role]);$accounts[$role]=$email;}
$vehicleTag=strtoupper(bin2hex(random_bytes(3)));$q=$db->prepare("INSERT INTO vehicles(plate_number,make,model,model_year,color,body_type,transmission,fuel_type,seating_capacity,daily_rate,current_mileage) VALUES(:plate,'Test','HTTP Maintenance',2026,'White','sedan','automatic','gasoline',5,1.00,2500)");$q->execute(['plate'=>'M8H-'.$vehicleTag]);$vehicle=(int)$db->lastInsertId();
[$mechanic,$mechanicCsrf]=m8login($accounts['mechanic']);$page=m8request($mechanic,'GET','/maintenance');m8httpcheck($page['status']===200&&str_contains($page['body'],'Maintenance'),'mechanic can access maintenance workspace');
$startDenied=m8request($mechanic,'POST','/maintenance/schedules/create',['_csrf'=>$mechanicCsrf,'vehicle_id'=>$vehicle,'schedule_name'=>'Denied '.$tag,'interval_time_days'=>'30','reason'=>'Denied']);m8httpcheck($startDenied['status']===403,'mechanic cannot configure maintenance schedules');
[$manager,$managerCsrf]=m8login($accounts['fleet_manager']);$create=m8request($manager,'POST','/maintenance/schedules/create',['_csrf'=>$managerCsrf,'vehicle_id'=>$vehicle,'schedule_name'=>'HTTP oil '.$tag,'interval_time_days'=>'30','interval_mileage'=>'1000','next_due_date'=>'','next_due_mileage'=>'','due_soon_days_override'=>'12','due_soon_mileage_override'=>'150','reason'=>'HTTP schedule acceptance']);m8httpcheck($create['status']===303,'fleet_manager can configure schedule and override');
$q=$db->prepare('SELECT schedule_id FROM maintenance_schedules WHERE vehicle_id=:vehicle AND schedule_name=:name');$q->execute(['vehicle'=>$vehicle,'name'=>'HTTP oil '.$tag]);$schedule=(int)$q->fetchColumn();m8httpcheck($schedule>0,'schedule override persisted');$q=$db->prepare('SELECT COUNT(*) FROM maintenance_schedule_logs WHERE schedule_id=:id AND new_due_soon_days_override=12 AND new_due_soon_mileage_override=150 AND CHAR_LENGTH(TRIM(reason))>0');$q->execute(['id'=>$schedule]);m8httpcheck((int)$q->fetchColumn()===1,'schedule-specific overrides are persisted with reasoned audit');
$start=m8request($mechanic,'POST','/maintenance/service/start',['_csrf'=>$mechanicCsrf,'vehicle_id'=>$vehicle,'schedule_id'=>$schedule,'title'=>'HTTP service '.$tag]);m8httpcheck($start['status']===303&&str_contains($start['headers']['location']??'','/maintenance/service?service_id='),'mechanic can start scheduled service');parse_str((string)parse_url($start['headers']['location']??'',PHP_URL_QUERY),$query);$service=(int)($query['service_id']??0);
$detail=m8request($mechanic,'GET','/maintenance/service?service_id='.$service);m8httpcheck($detail['status']===200&&str_contains($detail['body'],'Complete service'),'mechanic sees service actions');
[$auditor,$auditorCsrf]=m8login($accounts['auditor']);$auditorPage=m8request($auditor,'GET','/maintenance/service?service_id='.$service);m8httpcheck($auditorPage['status']===200&&!str_contains($auditorPage['body'],'Complete service')&&!str_contains($auditorPage['body'],'Save costs'),'auditor can read service without mutation controls');$auditPost=m8request($auditor,'POST','/maintenance/service/complete',['_csrf'=>$auditorCsrf,'service_id'=>$service,'mileage'=>'2501']);m8httpcheck($auditPost['status']===403,'auditor cannot complete maintenance service');
[$front,$frontCsrf]=m8login($accounts['front_desk']);$frontPage=m8request($front,'GET','/maintenance');m8httpcheck($frontPage['status']===403,'front_desk cannot access maintenance workspace');
$png=tempnam(sys_get_temp_dir(),'m8png');file_put_contents($png,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j2ioAAAAASUVORK5CYII=',true));$photo=m8multipart($mechanic,'/maintenance/service/photo',['_csrf'=>$mechanicCsrf,'service_id'=>$service,'phase'=>'before'],$png);m8httpcheck($photo['status']===303,'mechanic can upload validated before-service photo');$q=$db->prepare('SELECT photo_id,storage_path FROM maintenance_photos WHERE service_id=:service');$q->execute(['service'=>$service]);$photoRow=$q->fetch();if(!$photoRow)throw new RuntimeException('Uploaded maintenance photo metadata is missing.');m8httpcheck(str_starts_with((string)$photoRow['storage_path'],'maintenance/'),'maintenance photo is stored in private storage');$migrationDb=Database::migrationConnection();try{$migrationDb->exec('UPDATE maintenance_photos SET original_filename=\'tampered.png\' WHERE photo_id='.(int)$photoRow['photo_id']);m8httpcheck(false,'maintenance photos reject direct UPDATE');}catch(PDOException $e){m8httpcheck(str_contains(strtolower($e->getMessage()),'append-only'),'maintenance photos reject direct UPDATE');}try{$migrationDb->exec('DELETE FROM maintenance_photos WHERE photo_id='.(int)$photoRow['photo_id']);m8httpcheck(false,'maintenance photos reject direct DELETE');}catch(PDOException $e){m8httpcheck(str_contains(strtolower($e->getMessage()),'append-only'),'maintenance photos reject direct DELETE');}$guest=curl_init();curl_setopt_array($guest,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_COOKIEFILE=>'',CURLOPT_CONNECTTIMEOUT=>3,CURLOPT_TIMEOUT=>10]);$guestPhoto=m8request($guest,'GET','/maintenance/photo?photo_id='.(int)$photoRow['photo_id']);m8httpcheck($guestPhoto['status']===303,'unauthenticated maintenance photo request is rejected');$auditPhoto=m8request($auditor,'GET','/maintenance/photo?photo_id='.(int)$photoRow['photo_id']);m8httpcheck($auditPhoto['status']===200&&($auditPhoto['headers']['cache-control']??'')==='private, no-store','auditor can read private photo without caching');
foreach([$mechanic,$manager,$auditor,$front,$guest] as $client)curl_close($client);@unlink($png);if($failures>0){fwrite(STDERR,"M8 HTTP checks failed: $failures\n");exit(1);}echo "All M8 HTTP role and photo checks passed.\n";
